WITH enriched AS (SELECT src.*, b.supplier_name, b.country FROM products src LEFT JOIN suppliers b ON src.supplier_id = b.id) SELECT DATE_TRUNC('QUARTER', launch_date) AS quarter_start, CASE WHEN price >= 1220 THEN 'PREMIUM' ELSE 'STANDARD' END AS price_tier, SIZE(COLLECT_SET(category)) AS num_categories, CORR(stock_qty, cost) AS corr_stock_qty_cost FROM enriched GROUP BY ROLLUP (DATE_TRUNC('QUARTER', launch_date), CASE WHEN price >= 1220 THEN 'PREMIUM' ELSE 'STANDARD' END) ORDER BY num_categories DESC NULLS LAST;
